const emergencyRules = [
  /chest (pain|tightness|pressure)/,
  /heart attack/,
  /(can't|cannot|can not|unable to) breathe/,
  /(trouble|difficulty|hard to) breath/,
  /not breathing/,
  /short(ness)? of breath/,
  /unconscious|unresponsive|not responding|passed out|fainted|collapsed/,
  /(heavy|severe|profuse) bleeding|bleeding (that )?(won't|wont|will not|doesn't|does not) stop|won't stop bleeding/,
  /seizure|convulsion|having (a )?fit/,
  /stroke|face (is )?drooping|slurred speech/,
  /overdose|poisoned|poisoning/,
  /suicid|kill myself|want to die/,
  /seene (me|mein) (tez |bahut |zor se )?dard/,
  /saans (nahi|nhi)|saans (lene|lena) (me|mein) (takleef|dikkat)/,
  /behosh/,
  /khoon (bahut|ruk nahi|nahi ruk)/,
  /dil ka daura|daura pad/
];
const attackRules = [
  /ignore (all |your |the |previous |prior |above )*(rules|instructions|prompt|guidelines)/,
  /forget (all |your |the |previous |prior )*(rules|instructions)/,
  /system:|system prompt|you are now|developer mode|jailbreak|act as (an? )?(admin|root|developer)/,
  /(delete|drop|remove) (all )?(appointments|records|data|tables?)/,
  /(other|another|all) patients?'?s? (phone|number|details|records|data)/
];
const results = [];
for (const item of $input.all()) {
  const raw = String(item.json.text ?? "");
  const text = raw.toLowerCase().replace(/[’‘]/g, "'").replace(/ +/g, " ").trim();
  let emergency = false;
  let injection = false;
  let matched = "";
  for (const rule of emergencyRules) {
    const found = text.match(rule);
    if (found) { emergency = true; matched = found[0]; break; }
  }
  if (!emergency) {
    for (const rule of attackRules) {
      const found = text.match(rule);
      if (found) { injection = true; matched = found[0]; break; }
    }
  }
  results.push({ json: { text: raw, emergency: emergency, injection: injection, matched: matched } });
}
return results;
